"Klasická cvičení na pevném rozestavení. Překážky postavíš jednou a generátor k nim skládá různá pořadí.":"Klasyczne ćwiczenia na stałym ustawieniu. Przeszkody ustawiasz raz, a generator układa do nich różne kolejności.",
