"Tady jde Pawkur jen prohlížet. Ikona na ploše a upozornění jdou ze Safari: klepni na ⋯ vpravo nahoře a zvol Otevřít v Safari.":"Tutaj Pawkur można tylko przeglądać. Ikona na ekranie głównym i powiadomienia działają z Safari: stuknij ⋯ w prawym górnym rogu i wybierz Otwórz w Safari.",
