"Zadní strana, otočka doprava":"Od tyłu, owinięcie w prawo",
"Pes skok mine, oběhne křídlo doprava a skočí ho z druhé strany.":"Pies mija stacjonatę, obiega skrzydło w prawo i skacze z drugiej strony.",
"Pes běží u psovoda vlevo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Pies biegnie po lewej stronie przewodnika, więc owinięcie w prawo jest od wewnątrz (do przewodnika), a owinięcie w lewo od zewnątrz (od przewodnika).",
"Pes běží u psovoda vlevo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doprava venkem (od psovoda).":"Pies biegnie po lewej stronie przewodnika, więc owinięcie w prawo jest od wewnątrz (do przewodnika), a owinięcie w prawo od zewnątrz (od przewodnika).",
"Pes běží u psovoda vlevo, takže otočka doleva je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Pies biegnie po lewej stronie przewodnika, więc owinięcie w lewo jest od wewnątrz (do przewodnika), a owinięcie w lewo od zewnątrz (od przewodnika).",
