"Pes běží u psovoda vpravo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Pies biegnie po prawej stronie przewodnika, więc owinięcie w prawo jest od wewnątrz (do przewodnika), a owinięcie w lewo od zewnątrz (od przewodnika).",
"Pes běží u psovoda vpravo, takže otočka doprava je vnitřkem (k psovodovi) a otočka doprava venkem (od psovoda).":"Pies biegnie po prawej stronie przewodnika, więc owinięcie w prawo jest od wewnątrz (do przewodnika), a owinięcie w prawo od zewnątrz (od przewodnika).",
"Pes běží u psovoda vpravo, takže otočka doleva je vnitřkem (k psovodovi) a otočka doleva venkem (od psovoda).":"Pies biegnie po prawej stronie przewodnika, więc owinięcie w lewo jest od wewnątrz (do przewodnika), a owinięcie w lewo od zewnątrz (od przewodnika).",
