"Doleva a doprava je z pohledu psa. Když v Dráze psovoda nastavíš, na které straně psovoda pes běží, aplikace ukáže, jestli je otočka vnitřkem (k psovodovi), nebo venkem (od psovoda).":"Lewo i prawo są z perspektywy psa. Gdy w Linii przewodnika ustawisz, po której stronie przewodnika biegnie pies, aplikacja pokaże, czy owinięcie jest od wewnątrz (do przewodnika), czy od zewnątrz (od przewodnika).",
