"Zatím žádná trasa. Přepni na Trasa a klepej na překážky v pořadí.":"Na razie brak trasy. Przełącz na Trasa i stukaj przeszkody po kolei.",
"Zachovat poměr":"Zachowaj proporcje",
"Vyber překážku a klepnutím ji polož na plochu. Tažením ji přesuneš, posuvníkem otočíš.":"Wybierz przeszkodę i stuknięciem połóż ją na polu. Przeciągając, przesuniesz ją, a suwakiem obrócisz.",
"Klepej na překážky v pořadí, v jakém je pes poběží. Stejnou překážku můžeš použít víckrát. Otočku kolem křídla nebo zadní stranu nastavíš u skoku v seznamu pod plochou.":"Stukaj przeszkody w kolejności, w jakiej pies będzie je pokonywał. Tej samej przeszkody możesz użyć kilka razy. Owinięcie wokół skrzydła albo skok od tyłu ustawisz przy stacjonacie na liście pod polem.",
