"Překážky zůstanou na ploše, smaže se jen pořadí.":"Przeszkody zostaną na polu, usunie się tylko kolejność.",
"Rozestupy (FCI: po dráze 5–9 m, vzdušnou čarou nejvýš 7 m)":"Odległości (FCI: po linii psa 5–9 m, w linii prostej najwyżej 7 m)",
