"Rozestupy se měří po dráze psa, jak ji ukazuje plán, i se smyčkami otoček. Pravidla platí pro závody, na trénink si můžeš postavit cokoli.":"Odległości mierzy się po linii psa, tak jak pokazuje ją plan, razem z pętlami owinięć. Przepisy dotyczą zawodów, na trening możesz zbudować cokolwiek.",
"Fotku jako podklad vložíš ve webové verzi aplikace.":"Zdjęcie jako podkład dodasz w wersji webowej aplikacji.",
