"V téhle záložce nic nového není. Nové parkury mají štítek Nový a tečku u názvu záložky.":"W tej zakładce nie ma nic nowego. Nowe tory mają etykietę Nowy i kropkę przy nazwie zakładki.",
"Zatím tu nejsou žádné parkury trenérů. Pošli do chatu s Claudem screenshoty plánků a přepíše je sem i se jménem autora. Nebo v Plánu zvol Plánek z obrázku: aplikace překážky rozpozná, pořadí naklepeš a při ukládání vyplníš, kdo parkur stavěl.":"Na razie nie ma tu torów trenerów. Wyślij w czacie z Claude'em zrzuty ekranu planów, a przepisze je tutaj razem z nazwiskiem autora. Albo w Planie wybierz Plan toru ze zdjęcia: aplikacja rozpozna przeszkody, kolejność wystukasz, a przy zapisywaniu podasz, kto budował tor.",
"Zatím tu nemáš žádný vlastní parkur. Postav ho v Plánu nebo si otevři některý z A1–A3, uprav ho a ulož.":"Nie masz jeszcze własnego toru. Zbuduj go w Planie albo otwórz któryś z A1–A3, zmień go i zapisz.",
"V tomhle filtru nic není. Zkus jiný filtr nebo třídu.":"W tym filtrze nic nie ma. Spróbuj innego filtra albo klasy.",
"Přepsané plánky trenérů a rozhodčích pro vlastní trénink. Rozmístění překážek je přibližné, zdroj je uvedený u parkuru.":"Przepisane plany torów trenerów i sędziów do własnego treningu. Rozmieszczenie przeszkód jest przybliżone, źródło podano przy torze.",
"Parkury A1–A3 složil generátor v aplikaci podle Řádu agility FCI a podle toho, jak stavějí rozhodčí: dráha vede v obloucích a hadech, skoky stojí šikmo, tunely jsou i do oblouku a do U a dráha se kříží (A1 nejvýš jednou, A2 jednou až dvakrát, A3 dvakrát až třikrát). 15–22 překážek, start i cíl skokem, v A1 právě 3 zónové překážky, v A2 a A3 nejvýš 4. Otočky kolem křídla (v A3 aspoň dvě), v A3 vždy i zadní strana skoku.":"Tory A1–A3 ułożył generator w aplikacji według Regulaminu Agility FCI i tego, jak budują sędziowie: linia biegnie łukami i serpentynami, stacjonaty stoją ukośnie, tunele są też w łuk i w kształt U, a linia się krzyżuje (A1 najwyżej raz, A2 raz lub dwa razy, A3 dwa lub trzy razy). 15–22 przeszkód, start i meta na stacjonacie, w A1 dokładnie 3 przeszkody strefowe, w A2 i A3 najwyżej 4. Owinięcia wokół skrzydła (w A3 co najmniej dwa), w A3 zawsze też skok od tyłu.",
