"Plánky od rozhodčích a trenérů. Parkur podle plánku přeneseš v Plánu přes Plánek z obrázku (překážky se rozpoznají samy) a při ukládání vyplníš, kdo ho stavěl.":"Plany od sędziów i trenerów. Tor z planu przeniesiesz w Planie przez Plan toru ze zdjęcia (przeszkody rozpoznają się same), a przy zapisywaniu podasz, kto go budował.",
"HandlerMap 1.9":"HandlerMap 1.9",
"Plánovač agility parkurů: 90 parkurů podle pravidel FCI a stylu rozhodčích (oblouky, křížení, tunely do oblouku), parkury trenérů, kontrola pravidel, výpočet SČP a MČP, stopky s hodnocením a mezičasy, otočky kolem křídla a zadní strany skoků, 3D průlet, trénink paměti, videa s technikou, deník a statistiky.":"Planer torów agility: 90 torów według przepisów FCI i stylu sędziów (łuki, skrzyżowania, tunele w łuk), tory trenerów, kontrola przepisów, obliczanie SCT i MCT, stoper z oceną i międzyczasami, owinięcia wokół skrzydła i skoki od tyłu, przelot 3D, trening pamięci, filmy z techniką, dziennik i statystyki.",
"Novinky v 1.9: aplikace k instalaci do telefonu (Chrome → Instalovat aplikaci). V ní funguje výběr fotky a videa, ukládání obrázku, PDF a zálohy, plánek jde poslat přes Sdílet z galerie rovnou do čtečky, katalog parkurů i záloha v cloudu. Aktualizuje se sama.":"Nowości w 1.9: aplikacja do zainstalowania w telefonie (Chrome → Zainstaluj aplikację). Działa w niej wybór zdjęcia i wideo, zapisywanie obrazu, PDF i kopii zapasowej, plan można wysłać przez Udostępnij z galerii prosto do czytnika, katalog torów i kopia w chmurze. Aktualizuje się sama.",
"Novinky v 1.8: Plánek z obrázku přečte i trasu. Z čísel v kroužcích pozná pořadí, z nakreslené čáry směry skoků, vstupy do tunelů a zón, otočky kolem křídla a zadní strany. Chybějící kruh, skok daleký, dvojité břevno, zeď nebo kladinu dohledá u čísla. Nejistá místa označí otazníkem. V aplikaci pro Android jde plánek vložit i ze schránky.":"Nowości w 1.8: Plan toru ze zdjęcia odczytuje też trasę. Z numerów w kółkach rozpozna kolejność, z narysowanej linii kierunki skoków, wejścia do tuneli i na strefy, owinięcia wokół skrzydła i skoki od tyłu. Brakujące przeszkody (oponę, skok w dal, stacjonatę podwójną, mur albo kładkę) odnajdzie przy numerze. Niepewne miejsca oznaczy znakiem zapytania. W aplikacji na Androida plan można też wkleić ze schowka.",
"Novinky v 1.7: tlačítko Zkontrolovat nové parkury v záložce Parkury, nové parkury mají štítek Nový a tečku u záložky, přibyl parkur trenéra Euskadi Sextuple 2018 A1.":"Nowości w 1.7: przycisk Sprawdź nowe tory w zakładce Tory, nowe tory mają etykietę Nowy i kropkę przy zakładce, doszedł tor trenera Euskadi Sextuple 2018 A1.",
"Novinky v 1.6: nový generátor parkurů, náročnost a řazení parkurů, rozbor parkuru s vedením psovoda, odhadem času a simulací Stihnu to?, dráha podle velikosti psa, klasická cvičení a klubový parkur v generátoru, mezičasy naživo i z videa, chytrý trénink, předčítání trasy, plánek z obrázku, stavba v terénu s kompasem a sekce Začínáme pro štěňata.":"Nowości w 1.6: nowy generator torów, trudność i sortowanie torów, analiza toru z prowadzeniem przewodnika, szacowaniem czasu i symulacją Zdążę?, linia według wielkości psa, klasyczne ćwiczenia i tor klubowy w generatorze, międzyczasy na żywo i z wideo, inteligentny trening, czytanie trasy na głos, plan toru ze zdjęcia, budowa w terenie z kompasem i sekcja Pierwsze kroki dla szczeniąt.",
"Data se ukládají v tomhle zařízení. Sdílení kódem a cloudová záloha běží přes server Supabase a fungují v aplikaci pro Android. Uložení PDF a obrázku do telefonu a podklad z fotky fungují ve webové verzi.":"Dane są zapisywane na tym urządzeniu. Udostępnianie kodem i kopia w chmurze idą przez serwer Supabase i działają w aplikacji na Androida. Zapisywanie PDF i obrazu w telefonie oraz podkład ze zdjęcia działają w wersji webowej.",
