"Novinky v 1.13: 3D animace techniky ve Videích – pes a psovod na skutečných překážkách (skok, tunel, slalom, áčko, kladina, houpačka, kruh, skok daleký) i při vedení psa (čelo, záda, blind, otočky, zadní strana, start). Animace se stáhne až při otevření tématu, na slabším telefonu se sama zjednoduší a bez podpory 3D zůstane dosavadní 2D animace.":"Nowości w 1.13: animacje 3D techniki w Filmach – pies i przewodnik na prawdziwych przeszkodach (stacjonata, tunel, slalom, palisada, kładka, huśtawka, opona, skok w dal) i przy prowadzeniu psa (front cross, rear cross, blind, owinięcia, skok od tyłu, start). Animacja pobiera się dopiero po otwarciu tematu, na słabszym telefonie sama się upraszcza, a bez obsługi 3D zostaje dotychczasowa animacja 2D.",
"Novinky v 1.12: nová úvodní obrazovka Domů – série tréninkových dní, zaběhnuté parkury, průměrná rychlost a podíl čistých běhů, tlačítko Pokračovat na rozdělaný parkur, Parkury pro tebe podle třídy psa, Výzva dne a přehled tréninků v tomto týdnu. Parkur týdne: každý týden jeden parkur pro třídu, výsledek pošleš do žebříčku a porovnáš se s ostatními podle velikosti psa.":"Nowości w 1.12: nowy ekran Główna – seria dni treningowych, przebiegnięte tory, średnia prędkość i odsetek czystych biegów, przycisk Kontynuuj dla rozpoczętego toru, Tory dla Ciebie według klasy psa, Wyzwanie dnia i przegląd treningów w tym tygodniu. Tor tygodnia: co tydzień jeden tor dla każdej klasy, wynik wyślesz do rankingu i porównasz się z innymi według kategorii psa.",
"Novinky v 1.11: aplikace se aktualizuje hned a nabídne Obnovit, když je připravená nová verze. STOP na stopkách je dál od Mezičasů, větší tlačítka pro palec (počítadla chyb, překážky na ploše, strana psa L/P), parkury po dvou vedle sebe i na malém telefonu, plocha při klepání trasy neposkakuje, klávesnice nepřekrývá tlačítka. Kontrola FCI počítá mezi skoky i kruh a skok daleký, hlídá nejvýš 5 průběhů tunelem a SČP i MČP vychází z ukázané délky trati.":"Nowości w 1.11: aplikacja aktualizuje się od razu i proponuje Odśwież, gdy nowa wersja jest gotowa. STOP na stoperze jest dalej od Międzyczasów, większe przyciski pod kciuk (liczniki błędów, przeszkody na polu, strona psa L/P), tory po dwa obok siebie także na małym telefonie, pole nie podskakuje przy stukaniu trasy, klawiatura nie zasłania przycisków. Kontrola FCI liczy do przeszkód skokowych także oponę i skok w dal, pilnuje najwyżej 5 przejść przez tunel, a SCT i MCT wynikają z pokazanej długości toru.",
"Novinky v 1.10: tlačítko Zpět (↶ vedle Stavba / Trasa, na počítači Ctrl+Z) vrátí posunutí, otočení i smazání překážky a změny trasy. Když běží stopky, obrazovka nezhasne. Tažení překážky je plynulejší. Čas ručně jde zadat i jako 1:05,30. Plánek z obrázku při čtení nezamrzne telefon a kompas ve Stavbě v terénu funguje i na iPhonu. PDF se stavebním plánem se vejde i u čtvercové plochy. Parkur z kódu se před uložením zkontroluje, poškozená data už aplikaci neshodí. Obnova zálohy nahradí všechna data, a když se nepovede, nic se nezmění. Při plné paměti aplikace upozorní, že se změna neuložila. Při slabém signálu na cvičišti se aplikace otevře do 3 sekund z uložené verze a písmo funguje i offline.":"Nowości w 1.10: przycisk Cofnij (↶ obok Budowa / Trasa, na komputerze Ctrl+Z) cofa przesunięcie, obrót i usunięcie przeszkody oraz zmiany trasy. Gdy działa stoper, ekran nie gaśnie. Przeciąganie przeszkody jest płynniejsze. Czas ręcznie można wpisać też jako 1:05,30. Plan toru ze zdjęcia przy odczycie nie zawiesza telefonu, a kompas w Budowie w terenie działa też na iPhonie. PDF z planem budowy mieści się także przy kwadratowym polu. Tor z kodu jest sprawdzany przed zapisaniem, uszkodzone dane już nie wywracają aplikacji. Przywrócenie kopii zastępuje wszystkie dane, a gdy się nie uda, nic się nie zmienia. Przy pełnej pamięci aplikacja ostrzeże, że zmiana się nie zapisała. Przy słabym sygnale na placu treningowym aplikacja otwiera się w 3 sekundy z zapisanej wersji, a czcionka działa też offline.",
"zapne se po klepnutí na Stojím v rohu":"włączy się po stuknięciu Stoję w narożniku",
