"Hoopers: pes běží parkur z oblouků, sudů, plůtků a krátkých tunelů sám a psovod ho vede z prostoru 2 × 2 m (žlutý čtverec). Parkury H1–H3 složil generátor podle pravidel FCI Hoopers: start i cíl obloukem, aspoň polovina oblouků, vzdálenosti mezi překážkami a od psovoda podle třídy. Hodnotí se chyby, maximální čas jsou 3 minuty.":"Hoopers: pies sam pokonuje tor z obręczy, beczek, płotków i krótkich tuneli, a przewodnik prowadzi go ze strefy 2 × 2 m (żółty kwadrat). Tory H1–H3 ułożył generator według przepisów FCI Hoopers: start i meta na obręczy, co najmniej połowa obręczy, odległości między przeszkodami i od przewodnika zależne od klasy. Ocenia się błędy, maksymalny czas to 3 minuty.",
