"Členům skupiny přijde upozornění a den předem připomenutí. Parkur z Plánu se pošle skupině, běhy se pak sejdou v jejím žebříčku.":"Członkowie grupy dostaną powiadomienie, a dzień wcześniej przypomnienie. Tor z Planu zostanie wysłany grupie, a biegi trafią potem do jej rankingu.",
