"Podklad je moc velký, k parkuru se neuložil.":"Podkład jest za duży i nie został zapisany z torem.",
"Podklad se k parkuru neuložil, v telefonu je málo místa.":"Podkład nie został zapisany z torem, w telefonie brakuje miejsca.",
"Vyfoť nebo vyber plánek parkuru. Zobrazí se pod mřížkou a překážky na něj jen položíš. S parkurem uloženým v Moje zůstane jen v tomhle telefonu.":"Zrób lub wybierz zdjęcie planu toru. Pojawi się pod siatką, a przeszkody po prostu na nim położysz. Przy torze zapisanym w Moich zostanie tylko w tym telefonie.",
"Parkur se uložil jen tady, ve vestavěném prohlížeči. V aplikaci Pawkur ho zatím nemáš.":"Tor jest zapisany tylko tutaj, we wbudowanej przeglądarce. W aplikacji Pawkur jeszcze go nie masz.",
