"24\" Choice: pes do 22\" smí skákat 24\", časy má jako 20\". Slalom: Novice 6 tyčí, od Open 12. Bodování ze 100: odmítnutí, špatná překážka a chyba na stole −5 bodů, shozená tyčka a minutá zóna vyřazují (NQ). Časové chyby za každou celou sekundu nad SČP: Novice 1, Open 2, Excellent a Master 3 body; maximální čas je SČP + 20 s. Kvalifikace (Q): aspoň 85 bodů, v Master 100; v Excellent a Master žádná chyba na trati. Titul MACH: 750 bodů (sekunda pod SČP = bod) a 20 dvojitých Q v Master.":"24\" Choice: pies do 22\" może skakać 24\", a czasy ma jak 20\". Slalom: w Novice 6 tyczek, od Open 12. Ocena od 100 punktów: odmowa, zła przeszkoda i błąd na stole to −5 punktów, zrzucona tyczka i ominięta strefa oznaczają eliminację (NQ). Punkty za czas za każdą pełną sekundę ponad SCT: Novice 1, Open 2, Excellent i Master 3; maksymalny czas to SCT + 20 s. Kwalifikacja (Q): co najmniej 85 punktów, w Master 100; w Excellent i Master bez żadnego błędu na torze. Tytuł MACH: 750 punktów (każda sekunda poniżej SCT = punkt) i 20 podwójnych Q w Master.",
