"Délka trati a vzdálenosti na plánku v metrech, ve stopách, nebo jako u AKC: délka trati v yardech a vzdálenosti ve stopách. Rychlost je u stop a yardů v yardech za sekundu. Parkury se dál ukládají v metrech.":"Długość toru i odległości na planie w metrach, w stopach albo jak w AKC: długość toru w jardach, a odległości w stopach. Przy stopach i jardach prędkość jest w jardach na sekundę. Tory nadal zapisują się w metrach.",
