"Ulož si, kde stojí kolbiště, a aplikace tě k němu dovede. Zaměřené natočení použije Stavba v terénu a AR na place. Polohy zůstávají v tomhle zařízení a v tvé záloze; s parkurem odejdou, jen když ho sdílíš kódem i s polohou kolbiště.":"Zapisz, gdzie stoi ring, a aplikacja Cię do niego doprowadzi. Zmierzoną orientację wykorzysta Budowa w terenie i AR na placu. Położenia zostają na tym urządzeniu i w Twojej kopii zapasowej; z torem wychodzą tylko wtedy, gdy udostępniasz go kodem razem z położeniem ringu.",
"Hoopers: oblouky, sudy a tunely, bez skoků. Parkury Jumping patří pod Agility.":"Hoopers: obręcze, beczki i tunele, bez skoków. Tory Jumping należą do Agility.",
"Zavřít vysvětlení":"Zamknij wyjaśnienie",
"Přidat polohu kolbiště (pro AR a stavbu v terénu)":"Dodaj położenie ringu (dla AR i budowy w terenie)",
"Polohu kolbiště uvidí jen ten, kdo dostane kód. Do galerie ani skupině se neposílá.":"Położenie ringu zobaczy tylko ten, kto dostanie kod. Nie trafia do galerii ani do grupy.",
"Podle rohů":"Według narożników",
"Doladit":"Dopasuj",
"Doladit polohu":"Dopasuj położenie",
"Zem se zatím nenašla. Miř telefonem na zem a pomalu s ním pohybuj.":"Nie znaleziono jeszcze podłoża. Celuj telefonem w ziemię i powoli nim poruszaj.",
"Zamiř kroužek na stůl nebo na zem a klepni. Model se položí středem.":"Naceluj kółkiem na stół albo na ziemię i stuknij. Model położy się środkiem.",
"Model stojí. Pusť psa, nebo ho natoč v „Doladit“.":"Model stoi. Puść psa albo obróć go w „Dopasuj”.",
"Parkur stojí natočený podle kolbiště. Kompas může o pár stupňů ujet: dorovnej ho v „Doladit“, nebo polož parkur přesně „Podle rohů“.":"Tor stoi zorientowany według ringu. Kompas może się mylić o kilka stopni: wyrównaj go w „Dopasuj” albo połóż tor dokładnie „Według narożników”.",
"Dojdi do rohu kolbiště, který je na plánu vlevo nahoře, zamiř na něj zelený kroužek a klepni.":"Podejdź do narożnika ringu, który na planie jest w lewym górnym rogu, naceluj na niego zielone kółko i stuknij.",
"Teď dojdi podél dlouhé strany do rohu vpravo nahoře, zamiř na něj zelený kroužek a klepni.":"Teraz przejdź wzdłuż dłuższego boku do prawego górnego narożnika, naceluj na niego zielone kółko i stuknij.",
"Rohy jsou moc blízko u sebe. Dojdi do rohu vpravo nahoře, na druhý konec dlouhé strany.":"Narożniki są zbyt blisko siebie. Podejdź do prawego górnego narożnika, na drugim końcu dłuższego boku.",
"AR na place: položení přesně podle dvou rohů kolbiště, doladění o 1° a 25 cm, opravené Položit znovu":"AR na placu: dokładne położenie według dwóch narożników ringu, dopasowanie o 1° i 25 cm, naprawione Połóż ponownie",
"Kompas v AR, Stavbě v terénu a navigaci ke kolbišti počítá s rozdílem mezi magnetickým a zeměpisným severem":"Kompas w AR, Budowie w terenie i nawigacji do ringu uwzględnia różnicę między północą magnetyczną a geograficzną",
"Novinky ve verzi 3.5":"Nowości w wersji 3.5",
"Nový začátek: hned 3D průlet parkuru týdne, na psa se aplikace zeptá až při prvním běhu":"Nowy start: od razu przelot 3D nad torem tygodnia, o psa aplikacja zapyta dopiero przy pierwszym biegu",
"USA: plocha ve stopách a bez kontroly podle FCI u pravidel AKC":"USA: pole w stopach i bez kontroli według FCI przy zasadach AKC",
"Upozornění i polsky a německy":"Powiadomienia także po polsku i niemiecku",
"Takhle poběží tvůj pes parkur týdne. Parkury agility ve 3D, stopky a deník tréninku.":"Tak twój pies przebiegnie tor tygodnia. Tory agility w 3D, stoper i dziennik treningów.",
