"Návrh strany psa: u ostrých obratů je psovod uvnitř, mírné zatáčky se dají vést i zvenku. Změny strany: # (FCI chce aspoň 2).":"Propozycja strony psa: przy ostrych zwrotach przewodnik jest po wewnętrznej, łagodne zakręty można prowadzić też od zewnątrz. Zmiany strony: #1 (FCI wymaga co najmniej 2).",
