"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaného běhu psa. Odhad je nad SČP o # s.":"Model psa według wielkości: prędkość na zakrętach zależna od promienia, rozbieg, zwalnianie na strefach, w slalomie i na huśtawce. Dopasowany na podstawie #1 zapisanego biegu psa. Szacunek jest o #2 s ponad SCT.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaného běhu psa.":"Model psa według wielkości: prędkość na zakrętach zależna od promienia, rozbieg, zwalnianie na strefach, w slalomie i na huśtawce. Dopasowany na podstawie #1 zapisanego biegu psa.",
