"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Upraveno podle # zapsaných běhů psa.":"Model psa według wielkości: prędkość na zakrętach zależna od promienia, rozbieg, zwalnianie na strefach, w slalomie i na huśtawce. Dopasowany na podstawie #1 zapisanych biegów psa.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Až zapíšeš běhy psa, odhad se podle nich upraví. Odhad je nad SČP o # s.":"Model psa według wielkości: prędkość na zakrętach zależna od promienia, rozbieg, zwalnianie na strefach, w slalomie i na huśtawce. Gdy zapiszesz biegi psa, szacunek się do nich dopasuje. Szacunek jest o #1 s ponad SCT.",
"Model psa podle velikosti: rychlost v zatáčkách podle poloměru, rozběh, zpomalení na zónách, ve slalomu a na houpačce. Přidej psa ve Více › Psi a odhad bude pro něj. Odhad je nad SČP o # s.":"Model psa według wielkości: prędkość na zakrętach zależna od promienia, rozbieg, zwalnianie na strefach, w slalomie i na huśtawce. Dodaj psa w Więcej › Psy, a szacunek będzie dla niego. Szacunek jest o #1 s ponad SCT.",
